  "interactiveHelp.title": "Guida interattiva",
  "interactiveHelp.subtitle": "Fai clic su un elemento per saperne di più",
  "interactiveHelp.named": "«{name}»",
  "interactiveHelp.close": "Chiudi la finestra della guida",
  "interactiveHelp.nothing": "Qui non c'è nulla da spiegare. Punta il mouse su un pulsante, un campo, una maniglia o una finestra.",
  "interactiveHelp.loading": "Ricerca nella guida in corso…",
  "interactiveHelp.noIndex": "La guida non è ancora disponibile qui. Aprila dalla schermata iniziale.",
  "interactiveHelp.panelOnly": "Questa parte non ha un nome proprio. Il punto interrogativo della finestra apre la sezione della guida che la riguarda.",
  "interactiveHelp.sectionOnly": "La guida contiene una sezione su questa parte.",
