  "interactiveHelp.also": "Vedi anche nella guida",
  "interactiveHelp.search": "Cerca nella guida",
  "interactiveHelp.open": "Apri nella guida",
  "interactiveHelp.started": "Guida interattiva attiva: fai clic su un pulsante, un campo o una finestra per leggerne la spiegazione. Premi Esc per uscire.",
  "interactiveHelp.ended": "Guida interattiva disattivata",
  "shortcuts.interactiveHelp": "Attiva o disattiva la guida interattiva",
  "installHint.chromium": "Installa l'app usando l'icona a destra della barra degli indirizzi oppure dal menu del browser, scegliendo «Installa come app».",
  "installHint.safariMac": "In Safari: menu File → «Aggiungi al Dock».",
  "installHint.ios": "In Safari: icona Condividi → «Aggiungi alla schermata Home».",
  "installHint.firefox": "Firefox non consente di installare app, ma layerling continua a funzionare offline anche in questa scheda.",
  "welcome.moreLanguagesTitle": "La tua lingua",
  "welcome.moreLanguagesBody": "Il programma e la relativa guida sono disponibili in inglese, tedesco e altre 17 lingue. Puoi scegliere la lingua dal menu in alto a destra oppure dalle impostazioni nella schermata iniziale.",
  "welcome.moreOfflineTitle": "Funziona anche offline",
  "welcome.moreOfflineBody": "Dopo la prima visita, layerling si avvia anche senza Internet. Installalo come un normale programma: i tuoi progetti rimangono sul computer.",
  "welcome.moreAiTitle": "Crea con l'intelligenza artificiale",
  "welcome.moreAiBody": "Tramite l'interfaccia MCP, un assistente IA può creare e modificare forme direttamente nell'editor che apre. Per farlo serve una copia del programma eseguita sul tuo computer (con npm run dev oppure tramite l'immagine Docker). Su layerling.com il collegamento all'IA è disattivato.",
  "welcome.morePointsTitle": "Punti di riferimento",
  "welcome.moreSearchTitle": "Ricerca comandi",
  "welcome.moreSimplifyTitle": "Semplifica le mesh",
  "welcome.moreSimplifyBody": "Una mesh importata con un numero molto elevato di triangoli viene semplificata, riducendone drasticamente il numero. Puoi confrontare il risultato prima e dopo tramite un cursore: così operazioni come tagliare, raggruppare e spostare rimangono fluide.",
  "welcome.moreHistoryTitle": "Cronologia",
  "welcome.moreLookTitle": "Personalizza l'aspetto",
  "welcome.moreLookBody": "Nelle impostazioni puoi personalizzare lo sfondo e il piano di lavoro, le frecce degli assi X, Y e Z, le linee dei bordi dei solidi, i colori degli schizzi, il contrasto, le ombre e la direzione della luce, ad esempio per distinguere meglio i solidi scuri. Sui computer meno potenti, la modalità veloce disattiva in un colpo solo tutte le opzioni più pesanti.",
  "welcome.moreControlsTitle": "Mouse e mouse 3D",
  "welcome.moreControlsBody": "Permette di utilizzare i pulsanti del mouse come in Bambu Studio e OrcaSlicer: trascinando con il tasto sinistro su uno spazio vuoto si ruota la vista, mentre con il tasto destro la si sposta. Consente inoltre di controllare la vista con uno SpaceMouse nei browser Chrome ed Edge.",
  "welcome.moreTabletTitle": "Su un tablet",
  "welcome.moreTabletBody": "Un dito controlla il progetto come il pulsante sinistro del mouse; due dita ingrandiscono e spostano la vista. Una tastiera Bluetooth permette di usare le scorciatoie.",
  "welcome.moreHistoryBody": "Usa il cursore per rivedere qualsiasi stato precedente del progetto senza modificarlo. Puoi esportare quello stato, creare un nuovo progetto a partire da esso o recuperare singoli oggetti. Annulla e Ripeti indicano il passaggio che modificano, con la relativa misura; un elenco consente di saltare a qualsiasi passaggio.",
  "welcome.moreDrawingTitle": "Tavola tecnica per l'officina",
  "welcome.moreDrawingBody": "Esporta → Disegno: viste frontale, superiore e laterale in scala 1:1 su un foglio ISO, con dimensioni complessive, bordi nascosti e una tabella dei fori circolari. Esporta in PDF o SVG, per stampare il disegno o portarlo al tornio e alla fresatrice. La vista dall'alto in SVG o DXF va al taglio laser, se vuoi con ponti da stencil che tengono il centro di una o o di una b.",
  "welcome.moreSearchBody": "Premi Ctrl+K e digita il nome di uno strumento, di una forma o di un comando per raggiungerlo direttamente. La ricerca funziona in inglese e tedesco e mostra le scorciatoie da tastiera accanto a ogni risultato. Puoi cercare anche i solidi del progetto per nome.",
  "welcome.moreHelpTitle": "Guida interattiva",
  "welcome.moreHelpBody": "Premi Maiusc+F1 o il punto interrogativo, poi fai clic su un pulsante, un campo o una finestra: una piccola finestra mostra la sezione della guida relativa all'elemento.",
  "welcome.morePointsBody": "Fai clic con il tasto destro su un solido per contrassegnarne il centro, gli angoli o i punti medi degli spigoli. Questi punti non vengono stampati, ma consentono alle forme di agganciarsi con precisione: puoi, ad esempio, posizionare un foro esattamente al centro di un'altra parte.",
  "welcome.videosTitle": "Video su layerling",
  "welcome.videosHint": "Realizzati da altri utenti, non dal progetto. I collegamenti aprono YouTube in una nuova scheda; nessun contenuto viene caricato finché non fai clic.",
  "welcome.help": "Nell'editor, la sezione Guida contiene una breve guida e l'elenco di tutte le scorciatoie da tastiera. Nel piè di pagina, «Segnala un bug» salva il progetto insieme a tutte le informazioni necessarie per inviare una segnalazione sul forum o su GitHub.",
  "welcome.guideLink": "Leggi la guida utente completa, con immagini",
  "welcome.guideUrl": "/guide/index.html",
  "guide.helpLink": "Leggi la spiegazione nella guida utente",
  "guide.fullGuide": "Apri la guida utente completa con le immagini",
