  "cookieCutter.subtitle": "Una parete e una cornice attorno al contorno",
  "cookieCutter.cancel": "Chiudi taglia-biscotti",
  "cookieCutter.help": "Il contorno della selezione diventa una parete sottile, con un bordo di taglio e una cornice piatta attorno alla base. Le eventuali aperture interne, come quella della lettera «e», ricevono pareti proprie. In seguito puoi modificare parete, altezza e cornice nelle Proprietà.",
  "cookieCutter.support": "Pareti interne sostenute da",
  "cookieCutter.support.bridges": "Ponticelli",
  "cookieCutter.support.plate": "Piastra",
  "cookieCutter.supportBridgesHint": "Le barrette sul lato su cui si preme collegano le pareti interne a quella esterna e tra loro.",
  "cookieCutter.supportPlateHint": "Una piastra sottile riempie tutto il contorno sul lato su cui si preme: offre maggiore stabilità e aderisce meglio al piano di stampa, ma non permette di spingere fuori l'impasto dal retro.",
  "cookieCutter.plate": "Spessore della piastra",
  "cookieCutter.fillet": "Raccordi",
  "cookieCutter.filletHint": "Una piccola inclinazione nel punto in cui le pareti poggiano sulla cornice, sui ponticelli o sulla piastra, per evitare che le parti sottili si stacchino. 0 per nessun raccordo.",
  "cookieCutter.imprint": "Pareti interne più basse di",
  "cookieCutter.imprintHint": "Con 0, la parte interna viene ritagliata completamente. Abbassando le pareti interne, invece, si imprime soltanto il contorno: con una parete di 15 mm e un impasto spesso 5 mm, abbassandole di 3 mm si ottiene un'impronta profonda 2 mm.",
  "cookieCutter.mirror": "Specchia il contorno (il testo risulterà orientato correttamente)",
  "cookieCutter.working": "Creazione in corso…",
  "cookieCutter.apply": "Crea taglia-biscotti",
  "status.cookieCutterMade": "Taglia-biscotti creato: una parete e una cornice attorno al contorno. Puoi modificarle nelle Proprietà.",
  "status.cookieCutterNeedsShape": "Seleziona prima una forma o uno schizzo.",
  "status.cookieCutterNoOutline": "Non è presente alcun contorno sul piano di lavoro da cui ricavare un taglia-biscotti. Posiziona prima la forma sul piano.",
  "status.cookieCutterChanged": "Il progetto è cambiato durante la creazione del taglia-biscotti. Riprova.",
  "status.cookieCutterTooComplex": "Il contorno contiene troppi punti per creare un taglia-biscotti. Utilizza una forma più semplice.",
  "status.cookieCutterMadeFlat": "Taglia-biscotti creato con la parte superiore piatta: il contorno presenta gradini troppo corti per il bordo di taglio. Modifica la parete nelle Proprietà.",
  "editor.tool.flexi": "Giunti flessibili",
  "flexi.title": "Giunti flessibili",
  "flexi.subtitle": "Dividi un corpo piatto in segmenti mobili",
  "flexi.cancel": "Chiudi giunti flessibili",
  "flexi.help": "Il corpo viene tagliato trasversalmente in segmenti, con un giunto stampato direttamente in corrispondenza di ogni taglio, in modo che, una volta stampato, i segmenti possano ruotare lateralmente. Prima disponi il corpo in piano sul piatto di stampa: nei punti in cui verranno realizzati i giunti, dovrebbe avere un'altezza di circa 6 mm e una larghezza di almeno 12 mm.",
  "flexi.axis": "Taglia lungo",
  "flexi.axis.auto": "Lato più lungo",
  "flexi.axis.x": "X",
  "flexi.axis.z": "Y",
  "flexi.joints": "Giunti",
  "flexi.clearance": "Gioco",
  "flexi.clearanceHint": "Distanza attorno a ogni giunto. 0,4 mm è adatto alla maggior parte delle stampanti; aumenta il valore se i segmenti rimangono attaccati.",
  "flexi.swing": "Rotazione su ciascun lato",
  "flexi.bend": "Movimento degli elementi",
  "flexi.bend.side": "Ai lati",
  "flexi.bend.fold": "Su e giù",
  "flexi.fold": "Piegatura su e giù di",
  "flexi.helpFold": "Il corpo viene tagliato in bande lungo la sua lunghezza, con una cerniera stampata in posizione a ogni taglio. Dopo la stampa le bande si piegano su e giù, come un portachiavi flessibile. Appoggia prima il corpo in piano sul piano di stampa; nei punti delle cerniere deve essere alto almeno circa 5 mm e largo 15–20 mm.",
  "flexi.autoSize": "Dimensiona i giunti in base al corpo",
  "flexi.size": "Diametro del giunto",
  "flexi.evenLinks": "Segmenti tutti della stessa lunghezza",
  "flexi.start": "Primo giunto dall'inizio",
  "flexi.end": "Ultimo giunto dalla fine",
