  "flexi.error.notClosed": "Il corpo non è chiuso e non può essere diviso in segmenti. Chiudilo o correggilo prima di procedere.",
  "flexi.error.tooShort": "I giunti non entrano lungo il corpo. Riducine il numero oppure sposta più all'interno il primo e l'ultimo giunto.",
  "flexi.error.tooThin": "Il giunto {joint} non ha spazio sufficiente: in quel punto il corpo è largo solo {size} mm. Allarga il corpo in quel punto, riduci le dimensioni del giunto oppure sposta i giunti.",
  "flexi.error.foldTooThin": "Lo snodo {joint} non ha spazio: in quel punto il corpo è largo solo {size} mm, ma una cerniera pieghevole richiede circa {need} mm. Allarga il corpo in quel punto o sposta gli snodi.",
  "flexi.error.tooFlat": "Il giunto {joint} non ha spazio sufficiente: in quel punto il corpo è alto solo {size} mm. Un giunto richiede almeno circa 3 mm, preferibilmente 6 mm o più.",
  "flexi.error.tooClose": "Il giunto {joint} è troppo vicino a quello precedente: tra i giunti servono circa {size} mm. Riducine il numero oppure usa giunti più piccoli.",
  "flexi.error.empty": "Il segmento {link} risulterebbe vuoto. Riduci il numero di giunti.",
