  "lid.help": "Il coperchio segue il contorno del corpo e l'apertura superiore. Prima crea il corpo cavo, lasciandolo aperto nella parte superiore. Il coperchio viene posizionato accanto al corpo, capovolto con la piastra rivolta verso il basso e pronto per la stampa.",
