  "status.faceToolFailed": "Impossibile creare il solido con lo strumento Faccia: {message}",
  "status.honeycombConverted": "Struttura a nido d'ape convertita in uno schema di fori: {count}",
  "welcome.moreHolePatternTitle": "Schema di fori",
  "welcome.moreHolePatternBody": "Fai clic su una faccia piana di un corpo per distribuirvi dei fori: circolari, quadrati, rettangolari, esagonali o ad asola, disposti a griglia o sfalsati, con distanza, margine dal bordo e profondità configurabili (attraverso tutto il corpo o fino a una profondità specifica). Un'anteprima mostra i fori prima della creazione; rimangono normali fori raggruppati con il corpo, ideali per prese d'aria, griglie per altoparlanti, cestelli e contenitori. Oppure metti una corona di fori per viti lungo il bordo, uno su ogni angolo, con lamatura o svasatura se vuoi. Allo stesso modo si ripete una forma propria, rivetti o una lamiera mandorlata.",
  "welcome.moreFaceTitle": "Estrudi una faccia",
  "welcome.moreFaceBody": "Estrai una faccia piana del corpo o ricava una tasca, impostando il rientro dal bordo, gli angoli arrotondati e la profondità. L'anteprima mostra il risultato, anche sui file STL importati.",
  "welcome.moreTextureTitle": "Texture della superficie",
  "welcome.moreTextureBody": "Applica un rilievo a qualsiasi corpo, per migliorare la presa o per motivi estetici: zigrinature, scanalature, nido d'ape, mattoni, fibra di carbonio, corteccia, venature del legno, corde, immagini come mappe di altezza o testi. Le texture possono essere applicate attorno ai corpi rotondi oppure in piano lungo un asse. Fino a sei motivi sullo stesso corpo, ognuno sulle proprie facce.",
  "welcome.moreVaseTitle": "Vasi e contenitori",
  "welcome.moreVaseBody": "Una forma dedicata alla creazione di vasi, contenitori e paralumi: puoi personalizzare la forma del corpo, la sezione, la torsione, i motivi, i fori di drenaggio, il sottovaso e il coperchio. Puoi ottenere un modello pieno, adatto alla modalità vaso dello slicer, oppure cavo. Un coperchio da teiera è la parte superiore del vaso stesso, e il motivo prosegue oltre la giunzione.",
  "welcome.moreOffsetTitle": "Offset e ritaglio",
  "welcome.moreOffsetBody": "Ingrandisce o riduce un corpo di una distanza precisa, tutto attorno o solo lateralmente, per esempio per creare il gioco di un accoppiamento a pressione; oppure ritaglia una parte da un'altra mantenendo una distanza uniforme lungo il contorno, con una sola operazione.",
  "welcome.morePunchTitle": "Punzonare",
  "welcome.morePunchBody": "taglia il contorno di un corpo dritto attraverso un altro, ovunque si trovi davanti: la sagoma di una teiera attraverso un cartello, un logo attraverso un coperchio. Sposta o ruota il punzone e punzona di nuovo; un gioco lascia passare un pezzo stampato.",
  "welcome.moreClearanceTitle": "Controlla il gioco",
  "welcome.moreClearanceBody": "Prima di stampare parti che devono muoversi - una cerniera stampata già montata, un giocattolo flexi, un coperchio nella sua scatola - trova le coppie che si sovrappongono, si toccano o sono più vicine del gioco che imposti.",
  "guide.select.holePattern": "Modello di fori (pulsante nella barra degli strumenti accanto a Schema, clic destro su un solido oppure Ctrl+K): fai clic su una faccia piana, quindi imposta forma, dimensioni, spaziatura, disposizione, margine e profondità. I fori sono mostrati in anteprima; «Crea» li aggiunge come fori raggruppati con il corpo. Separa il gruppo per liberarli.",
  "guide.select.faceTool": "Faccia (pulsante nella barra degli strumenti accanto a Modello di fori, clic destro su un solido oppure Ctrl+K): fai clic su una faccia piana, scegli Esterno o Interno, quindi imposta il rientro dal bordo, il raggio degli angoli e la profondità. Viene aggiunto uno schizzo raggruppato con il corpo.",
  "scalePercent.errorTooSmall": "\"{name}\" diventerebbe più piccolo di 0,01 mm.",
  "scalePercent.errorTooLarge": "\"{name}\" diventerebbe più grande di quanto consentito dalla sua forma. Imposta un \"Limite dimensione personalizzata\" più alto nelle impostazioni predefinite delle forme oppure scegli una percentuale più bassa.",
