  "status.meshTooDense": "Questa mesh contiene {triangles} triangoli. La lavorazione degli spigoli ne gestisce {limit}; oltre questo limite, il kernel richiede più tempo di quanto valga la pena aspettare. Per una forma dell'elenco delle forme, usa per ora le impostazioni specifiche. Per una parte importata, importala come STEP oppure salvala prima con meno triangoli.",
  "status.meshDenseAsk": "Questa mesh contiene {triangles} triangoli, più dei {limit} per cui è stato progettato il trattamento degli spigoli. Oltre questo limite, l'operazione può richiedere molti minuti e bloccare la pagina. Se dovessi chiuderla, perderesti tutte le modifiche non salvate. Salva prima il progetto.\n\nVuoi procedere comunque?",
  "status.threadTooDense": "Una filettatura è composta da {triangles} triangoli, troppi per la lavorazione degli spigoli, che si ferma a {limit}. Aggiungi quindi la filettatura dopo la lavorazione degli spigoli: applica prima lo smusso o il raccordo al corpo, poi crea la filettatura. Lo smusso della testa nelle proprietà elimina il bordo della testa della vite senza questo passaggio aggiuntivo.",
  "status.vaseTooDense": "Questo vaso ha {triangles} triangoli, più dei {limit} gestibili con lo svuotamento e il trattamento degli spigoli. Il vaso si svuota da solo e ha un coperchio proprio: in «Costruisci» scegli «Svuota con parete» e seleziona un coperchio nella scheda Accessori.",
