  "gear.involuteHint": "Circonferenza primitiva {pitch} mm. Ingrana con qualsiasi ingranaggio di modulo {module}; distanza tra i centri = (n. denti del primo + n. denti del secondo) × modulo / 2.",
  "gear.profileRound": "Arrotondato",
  "gear.roundHint": "Denti arrotondati ad arco, più facili da stampare su ingranaggi piccoli e con presa fluida sulle manopole. Circonferenza primitiva {pitch} mm. Ingrana con qualsiasi ingranaggio arrotondato di modulo {module}; distanza tra i centri = (numero di denti + numero di denti) × modulo / 2.",
