  "thread.flankAngleHint": "L'angolo tra i due fianchi di un dente. 60° corrisponde a una filettatura a V acuta, 30° a una filettatura trapezoidale. Con un angolo di 90° o inferiore, nessun fianco è più piatto di 45°, quindi la filettatura può essere stampata senza supporti.",
