  "prop.threadChamferBottom": "Smusso, estremità inferiore",
  "thread.axialClearanceHint": "Gioco aggiuntivo lungo la filettatura, in mm, oltre al gioco radiale: ogni dente del dado diventa più sottile di questa quantità, mentre il diametro rimane invariato. Per una filettatura che gira liberamente senza oscillare lateralmente, mantieni il gioco radiale intorno a 0,2–0,3 e imposta qui 0,2. A 0, il gioco dipende solo dal gioco radiale, che apre i fianchi soltanto della metà circa.",
  "thread.clearanceHint": "Spazio aggiuntivo sull'intero diametro. Una filettatura stampata richiede più spazio di quanto si possa pensare: la distanza tra i fianchi è solo circa la metà del valore impostato. Circa 0,3 è stretto, 0,4 è normale, 0,5 è largo. Stampa prima una coppia di prova.",
  "thread.boltClearanceHint": "Riduce lo spessore della vite di questa quantità, per un dado metallico che non ha gioco proprio (da 0,3 a 0,4, come quello necessario per un dado stampato). Con un dado stampato, lascia 0 e assegna il gioco al dado.",
