  "snapFit.strainTough": "Si allunga del {strain} % alla radice: troppo per il PLA, va bene per PETG o ABS (fino al 4 % circa). Un braccio più lungo o più sottile si piega meno.",
  "snapFit.strainTooMuch": "Si allunga del {strain} % alla radice: si romperà. Allunga o assottiglia il braccio, o riduci il sottosquadro.",
  "snapFit.leadHint": "Rispetto alla direzione d'inserimento: 30° entra facilmente, meno entra più dolcemente.",
  "snapFit.retainHint": "90° tiene per sempre, 45° si può staccare di nuovo.",
  "snapFit.footHint": "La piastra da cui pende il braccio, unita al coperchio. 0: senza base.",
