  "rib.gusset": "Fazzoletto",
  "rib.straightHint": "Irrigidisce un fondo o una parete. Più di una in fila con Crea schema ripetuto.",
  "rib.gussetHint": "Un triangolo che sostiene una parete contro il fondo: il lato verticale va contro la parete.",
  "rib.thicknessHint": "Circa spessa come la parete o un po' meno, un multiplo della larghezza di linea: 0,8 o 1,6 mm con un ugello da 0,4 mm.",
