  "inspector.surfaceCrackSeed": "Seme",
  "inspector.surfaceCrackSeedHint": "A parità di seme, le crepe rimangono identiche; cambiandolo, vengono generate nuove crepe. La lunghezza è espressa in percentuale dell'altezza, dal bordo superiore verso il centro, in percentuale del raggio.",
  "inspector.surfaceCrackGold": "Riempimento in oro come parte separata",
  "inspector.surfaceCrackRecess": "Incassamento dell'oro",
  "inspector.surfaceCrackGoldHint": "Il riempimento delle crepe diventa una parte separata in oro, da realizzare con un secondo filamento; la sua superficie si trova a questa distanza sotto la superficie. Per ottenere questo effetto, il motivo penetra nel corpo.",
  "status.surfaceNoCracks": "Nessuna crepa è riuscita ad attraversare questo corpo. Prova un punto di partenza diverso (con «Casuale» puoi iniziare in qualsiasi punto), crepe più lunghe oppure applica il motivo a più facce.",
