  "surfaceTexture.carbonTwill31": "Twill 3/1",
  "surfaceTexture.carbonTwill22Hint": "Ogni banda passa sopra due bande trasversali e sotto le due successive: è l'intreccio diagonale regolare tipico di molti componenti in fibra di carbonio.",
  "surfaceTexture.carbonTwill21Hint": "Sopra due bande e sotto una: le bande longitudinali appaiono lunghe, quelle trasversali più corte.",
  "surfaceTexture.carbonTwill31Hint": "Sopra tre bande e sotto una: le bande longitudinali sono lunghe, quelle trasversali compaiono solo in brevi tratti tra di esse.",
  "inspector.surfaceCarbonCross": "Larghezza delle bande trasversali",
  "inspector.surfaceCarbonHint": "Con larghezza delle bande trasversali pari a 0, le bande sono larghe quanto quelle verticali. Valori maggiori o minori creano un intreccio irregolare. Sui corpi rotondi, la larghezza delle bande viene leggermente adattata per chiudere l'intreccio.",
  "inspector.surfaceSeed": "Disposizione",
  "inspector.surfaceSeedHint": "Un numero diverso dispone nuovamente le celle o la grana.",
  "inspector.surfaceImage": "Immagine",
  "inspector.surfaceImageLoad": "Carica un'immagine…",
  "inspector.surfaceImageHint": "Le zone chiare diventano rilievi fino alla profondità massima, mentre quelle scure rimangono invariate. L'immagine personalizzata viene salvata nel progetto in scala di grigi, con un massimo di 256 punti per lato. La texture mantiene la larghezza impostata e l'altezza proporzionale all'immagine.",
  "inspector.surfaceTileHeight": "Altezza della texture (0 = come nell'immagine)",
  "inspector.surfaceImageHeight": "Altezza dell'immagine",
  "inspector.surfaceImageOnceHint": "L'immagine viene impressa una sola volta, come un'etichetta: «Disposizione intorno» e «Altezza» ne fissano il centro, come per un testo. Al di fuori la superficie resta liscia; «Profondità» e «Direzione» stabiliscono quanto sporge o è incisa. Un'altezza dell'immagine pari a 0 ne mantiene le proporzioni. Se sono selezionate delle facce, l'immagine finisce sempre su di esse.",
  "inspector.surfaceImageTurn": "Rotazione (°)",
  "inspector.surfaceImageInvert": "Inverti chiaro e scuro",
  "inspector.surfaceImageBlur": "Ammorbidisci",
  "inspector.surfaceImageTiling": "Ripetizione della texture",
  "inspector.surfaceGrainHint": "La grana viene distribuita nello spazio anziché proiettata sulla superficie: non presenta giunzioni né deformazioni ed è uniforme su qualsiasi forma.",
  "surfaceTexture.bark": "Corteccia",
