  "surfaceTexture.barkPineHint": "Lunghe placche separate da solchi, disposte a diverse altezze in strati sovrapposti.",
  "surfaceTexture.barkSpruceHint": "Piccole squame arrotondate, sovrapposte come tegole.",
  "surfaceTexture.barkBirchHint": "Superficie liscia, con brevi lenticelle trasversali e, qua e là, linee di sfaldamento.",
  "surfaceTexture.barkBeechHint": "Superficie liscia, con leggere ondulazioni e motivi a spina di pesce sotto le vecchie cicatrici dei rami.",
