  "surfaceTexture.woodCutQuarterSawn": "Tavola, taglio radiale",
  "surfaceTexture.woodCutLogHint": "Il midollo attraversa il centro del corpo: alle estremità si vedono gli anelli annuali, mentre sui lati compaiono le venature di un tronco senza corteccia.",
  "surfaceTexture.woodCutFlatSawnHint": "Il midollo corre sotto la tavola, lungo il lato più lungo: gli anelli formano archi sulla superficie.",
  "surfaceTexture.woodCutQuarterSawnHint": "Il midollo corre accanto alla tavola: gli anelli formano linee dritte sulla superficie e, nel caso della quercia, i raggi midollari appaiono come macchie.",
  "inspector.surfaceRingWidth": "Larghezza degli anelli",
  "inspector.surfaceEndRings": "Anelli annuali sulle estremità",
  "inspector.surfaceWoodHint": "Le venature seguono la struttura interna del corpo, come in un vero pezzo di legno: anelli stretti producono venature fini, quelli larghi venature più grossolane; sulle estremità compaiono anelli coerenti con quelli laterali.",
