  "inspector.surfaceBrickHint": "Lunghezza e altezza sono misurate da fuga a fuga. Le dimensioni vengono leggermente adattate per far entrare mattoni interi: sui corpi rotondi, da un bordo all'altro di una faccia piana, e dal fondo alla sommità.",
