  "vaseNote.meshLying": "Nessuna faccia piana appoggia sul fondo (la base è arrotondata oppure il pezzo è coricato?). L'asse è sempre quello verticale (Z): prima raddrizza il pezzo nello slicer e salvalo nuovamente.",
