  "vaseCheck.conflictLamp": "il paralume",
  "vaseCheck.watertightHollow": "A tenuta d'acqua: parete e fondo devono essere spessi almeno {mm} mm. Nello slicer imposta almeno tre linee di parete e cinque strati sul fondo; è preferibile aumentare leggermente anche il flusso o la temperatura. Prima di utilizzarlo, prova la tenuta con acqua sopra il lavandino.",
  "vaseCheck.watertightVaseMode": "A tenuta d'acqua in modalità vaso: una linea più larga (circa 0,6–0,8 mm con ugello da 0,4 mm) e una temperatura leggermente più alta rendono impermeabile la parete singola. Le nervature interne o la doppia parete la rendono più resistente. Prima di utilizzarlo, prova la tenuta con acqua sopra il lavandino.",
