  "vaseCheck.floorThicker": "Fondo ispessito a {mm} mm per evitare che gli alloggiamenti o gli incavi lo attraversino.",
  "vaseCheck.floorLamp": "Fondo ispessito a 2,5 mm per sostenere il paralume in corrispondenza del portalampada.",
  "vaseCheck.lampHoleTooBig": "Il foro per il portalampada (Ø {mm} mm) non entra nel fondo: aumenta il diametro del vaso nella parte inferiore.",
