  "vaseCheck.lampStanding": "Da appoggio: fissa il portalampada nel foro sul fondo (Ø {mm} mm) con la ghiera del paralume; il cavo passa attraverso il piede cavo. Verifica le misure e assicurati che il piede sia abbastanza alto da contenere il corpo del portalampada.",
  "vaseCheck.lampStandingNotch": "Da appoggio: fissa il portalampada nel foro sul fondo (Ø {mm} mm) con la ghiera del paralume; il cavo passa attraverso il piede cavo e la fessura. Verifica le misure e assicurati che il piede sia abbastanza alto da contenere il corpo del portalampada.",
