  "vaseCheck.slitsKept": "Slicer: modalità vaso a spirale attiva, larghezza della linea esterna {line} mm (come impostato qui). Le fessure ({slit} mm) vengono mantenute con le impostazioni predefinite; le due linee di una nervatura distano {slit} mm. Per unirle saldamente: imposta una larghezza delle fessure di 0,03 mm e \"Raggio chiusura del gap\" a 0,01 mm nello slicer (PrusaSlicer, OrcaSlicer, Bambu Studio).",
  "vaseCheck.slitsGap": "Slicer: modalità vaso a spirale attiva, larghezza della linea esterna {line} mm (come impostato qui). Importante: imposta \"Raggio chiusura del gap\" (PrusaSlicer, OrcaSlicer, Bambu Studio) a un massimo di {radius} mm; altrimenti lo slicer chiude le fessure da {slit} mm e stampa una parete liscia.",
