  "export.stl.description": "Mesh per stampa 3D",
  "export.stl.note": "Ideale per slicer e stampa 3D. La geometria viene esportata come mesh triangolare. In Chrome ed Edge scegli una volta la cartella e il nome; le successive esportazioni STL del progetto verranno salvate nello stesso file, a meno che tu non inserisca un altro nome: in tal caso ti verrà chiesto nuovamente dove salvare.",
