  "export.dxf.description": "Contorno per taglio laser",
  "export.dxf.note": "Esporta il contorno visto dall'alto per le officine di taglio laser: linee, archi e cerchi veri sul layer 0 in bianco, in millimetri. I corpi che si toccano diventano un unico contorno.",
  "export.dxf.noteFootprint": "Esporta solo i contorni con cui gli oggetti poggiano sul piano di lavoro, per le officine di taglio laser: linee, archi e cerchi veri sul layer 0 in bianco, in millimetri.",
  "export.lyl.description": "Formato di progetto proprietario di layerling",
  "export.lyl.note": "Conserva il progetto modificabile, la cronologia di annullamento/ripristino, gli schizzi, i gruppi, i dati CAD e le sorgenti importate. Anche i vecchi file .skf possono essere aperti e vengono salvati come .lyl. In Chrome ed Edge scegli la cartella e il nome del file; premendo Ctrl+S salverai nuovamente nello stesso file. Un progetto aperto da un file viene salvato nello stesso file.",
